/* URY v16 desk navigation (T24): sidebar, dock and shell. frappe-desk.css already styles .body-sidebar / .dock / .standard-sidebar-item;
   this file only carries what frappe scopes to <body> classes or media queries (dock-pinned, dock-active, below-md drawer) and the mock's pinned heights. */
.ury-desk { --ury-desk-h: 900px; }
.ury-desk .body-sidebar,
.ury-desk.body-sidebar-container .body-sidebar { height: var(--ury-desk-h); }

/* ---- dock: body.dock-pinned .dock (dock.scss) ---- */
.ury-desk-dock--pinned {
  width: calc(var(--dock-width) + 1px);
  position: relative; top: auto; inset-inline-start: auto; left: auto;
  transform: none; transition: none; flex: 0 0 auto;
  height: var(--ury-desk-h); max-height: none;
  border-radius: 0; box-shadow: none;
  border-inline-end: 1px solid var(--outline-gray-1);
  padding-top: calc(var(--spacing) * 2);
  overflow: hidden;
}
.ury-desk-dock--pinned .dock-items {
  width: calc(100% + var(--spacing) * 5.5);
  margin-inline: calc(var(--spacing) * -2.75);
  padding-block: var(--spacing);
  min-height: 0; overflow-y: auto; scrollbar-width: none;
}
.ury-desk-dock--pinned .dock-logo .header-logo { width: 32px; height: 32px; }
.ury-desk-dock--pinned .dock-user { display: flex; }
.ury-desk-dock--pinned .dock-user-button .avatar,
.ury-desk-dock--pinned .dock-user-button img { width: 28px; height: 28px; }
/* body.dock-open .dock: the floating tray, revealed (fixed, left 8, vertically centred) */
.ury-desk-dock--floating { transform: translate(0, -50%); }
.ury-desk-dock-stage { position: relative; width: 192px; height: var(--ury-desk-h); }
.ury-desk-dock-stage .ury-desk-dock--pinned { position: absolute; inset-block-start: 0; inset-inline-start: 0; }
/* tooltip: hovered tile gets its hover fill; the plain tooltip sits 10px to the side of the tile (Tooltip side=right, offset=10) */
.ury-desk-dock .dock-item.is-hover { background: var(--surface-gray-2); color: var(--dock-ink-hover); }
.ury-desk-tooltip { position: absolute; inset-inline-start: calc(var(--dock-width) + 1px + 10px); inset-block-start: 185px; white-space: nowrap; }
.ury-desk-tooltip { transform: translateY(-50%); }

/* ---- sidebar: edge + collapse arrow shown while the pointer is on the edge (.sidebar-edge:hover) ---- */
.ury-desk-sidebar .sidebar-edge.is-hover::after { background: var(--outline-gray-3); }
.ury-desk-sidebar .sidebar-collapse-arrow.is-visible { opacity: 1; pointer-events: auto; }
.ury-desk-sidebar-stage { position: relative; width: calc(var(--sidebar-width) + 12px); height: var(--ury-desk-h); }
.ury-desk-sidebar-stage > .body-sidebar-container.expanded { width: var(--sidebar-width); }
.ury-desk-sidebar-stage > .body-sidebar-container:not(.expanded) { width: var(--sidebar-collapsed-width); }

/* ---- sidebar: below md the panel is a drawer over a dimmed page (sidebar.scss media-breakpoint-down(sm)) ---- */
.ury-desk-drawer { position: relative; overflow: hidden; background: var(--bg-color); }
.ury-desk-drawer .ury-desk-drawer-page { position: absolute; inset: 0; }
.ury-desk-drawer .body-sidebar-container { position: absolute; inset-block: 0; inset-inline-start: 0; height: 100%; }
.ury-desk-drawer .body-sidebar { position: absolute; top: 0; bottom: 0; height: 100%; }
.ury-desk-drawer .sidebar-edge,
.ury-desk-drawer .sidebar-collapse-arrow { display: none; }
.ury-desk-drawer .body-sidebar-container.expanded .overlay {
  display: block; position: absolute; z-index: 1021; overflow: auto;
  inset-inline-start: var(--sidebar-width); width: calc(100% - var(--sidebar-width)); height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
}

/* ---- shell: <body class="desktop-page dock-active dock-pinned"> as a flex row ---- */
.ury-desk-shell { display: flex; background: var(--bg-color); color: var(--text-color); }
.ury-desk-shell-row { display: flex; width: 100%; height: 100%; }
.ury-desk-shell .body-sidebar-container { flex: 0 0 auto; }
.ury-desk-main { flex: 1 1 0; min-width: 0; }
.ury-desk-main-col { display: flex; flex-direction: column; height: 100%; }
.ury-desk-page-body { flex: 1 1 auto; min-height: 0; }
.ury-desk-shell .navbar-container {
  display: flex; align-items: center; gap: 10px; justify-content: space-between; width: 100%;
  padding: 8px 12px; box-sizing: border-box; height: 49px; border-bottom: 1px solid var(--border-color);
}
.ury-desk-shell #brand-logo { width: auto; }
/* body.dock-pinned.dock-active: the dock owns search and notifications, the user chip, and the sidebar header's mark */
.ury-desk-shell .body-sidebar .dropdown-navbar-user { display: none; }
.ury-desk-shell .body-sidebar .standard-items-band > .navbar-modal-search-mobile,
.ury-desk-shell .body-sidebar .standard-items-band > .sidebar-notification { display: none; }
.ury-desk-shell .body-sidebar .standard-items-band { padding-top: 0; margin-bottom: 0; }
.ury-desk-shell .body-sidebar-container.expanded .sidebar-header { padding-left: 12px; padding-inline-start: 12px; padding-inline-end: 15px; }
.ury-desk-shell .body-sidebar-container.expanded .sidebar-header .header-logo { display: none; }

/* ---- RTL: frappe's sidebar rules use physical left/right ---- */
[dir="rtl"] .ury-desk .title-container { text-align: right; }

/* dock.scss .dock-item .dock-item-dot: unread dot on the bell's corner (not in the compiled frappe-desk.css) */
.ury-desk-dock .dock-item .dock-item-dot {
  position: absolute; top: calc(var(--spacing) * 1.25); inset-inline-end: calc(var(--spacing) * 1.25);
  width: calc(var(--spacing) * 1.75); height: calc(var(--spacing) * 1.75); padding: 0; min-width: 0;
  border-radius: var(--radius-full, 9999px); border: 1px solid var(--dock-bg); background: var(--ink-gray-8);
  font-size: 0; overflow: hidden;
}

/* T25: URY v16 desk workspace widgets (frappe/public/scss/desk/desktop.scss + page.scss).
   Number card, shortcut and link card are .widget boxes placed on the 12-col editor.js grid (.ce-block col-N). */
.ury-ws { padding: 10px 20px 0; }
.ury-ws .codex-editor__redactor { display: flex; flex-wrap: wrap; flex-direction: row; margin: 0 -4px; }
.ury-ws .ce-block { width: 100%; box-sizing: border-box; }
.ury-ws .ce-block.col-3 { width: 25%; }
.ury-ws .ce-block.col-4 { width: 33.3333%; }
.ury-ws .ce-block.col-6 { width: 50%; }
.ury-ws .ce-block.col-12 { width: 100%; }
.ury-ws .ce-block__content { max-width: 100%; height: 100%; padding: 7px; box-sizing: border-box; }
.ury-ws .ce-block__content > div { height: 100%; }
.ury-ws .ce-header { margin: 0; flex: 1; }
.ury-ws .ce-header .h4 { font-size: var(--text-lg); color: var(--text-light); }
.ury-ws .ce-header .h4 b { font-weight: 600; }
.ury-ws .ce-spacer { height: 30px; }
.ury-ws-clip { overflow: hidden; height: 100%; }

.ury-ws .widget { display: flex; flex-direction: column; min-height: 1px; padding: 7px; box-sizing: border-box; border-radius: var(--radius-lg); height: 100%; background-color: var(--card-bg); text-align: start; }
.ury-ws .widget .widget-head { display: flex; justify-content: space-between; align-items: center; }
.ury-ws .widget .widget-label { min-width: 0; }
.ury-ws .widget .widget-title { display: flex; align-items: center; font-size: var(--text-base); font-weight: 500; line-height: 1.3em; color: var(--text-color); cursor: default; }
.ury-ws .widget .widget-control { opacity: 0; height: 0; position: relative; }
.ury-ws .ellipsis { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* number card: title 13px ink-gray-5, number 17/600, padding 8 8 8 12, control hidden */
.ury-ws .widget.number-widget-box { border: 1px solid var(--border-color); padding: 8px 8px 8px 12px; gap: 6px; cursor: pointer; }
.ury-ws .number-widget-box .widget-title { font-size: 13px; font-weight: 400; color: var(--ink-gray-5); }
.ury-ws .number-widget-box .widget-body { text-align: start; }
.ury-ws .number-widget-box .widget-content { display: flex; flex-direction: column; gap: 6px; }
.ury-ws .number-widget-box .number { font-size: 17px; font-weight: 600; line-height: 1.35; color: var(--ink-gray-8); }
.ury-ws .number-widget-box .percentage-stat-area { display: inline-flex; align-items: center; gap: 2px; font-size: 13px; font-weight: 500; }
.ury-ws .number-widget-box .percentage-stat-area .icon { margin: 0; }
.ury-ws .number-widget-box .green-stat { color: var(--ink-green-7); }
.ury-ws .number-widget-box .red-stat { color: var(--ink-red-7); }
.ury-ws .number-widget-box .grey-stat { color: var(--ink-gray-6); }
.ury-ws .number-widget-box .stat-label { color: var(--ink-gray-5); font-weight: 400; margin-inline-start: 4px; }

/* shortcut: 60px box, p10 12, 1px border */
.ury-ws .widget.shortcut-widget-box { height: 60px; padding: 10px 12px; border: 1px solid var(--border-color); cursor: pointer; }
.ury-ws .shortcut-widget-box .widget-title { cursor: pointer; font-size: var(--text-lg); }

/* link card */
.ury-ws .widget.links-widget-box { padding: 16px 8px 0; background-color: transparent; }
.ury-ws .links-widget-box .widget-head .widget-label .widget-title { font-size: 13px; font-weight: 500; color: var(--ink-gray-9); }
.ury-ws .links-widget-box .widget-body { display: flex; flex-direction: column; margin-top: 4px; }
.ury-ws .links-widget-box .link-item { display: flex; padding-block: 3px; font-size: 13px; font-weight: 400; color: var(--ink-gray-6); text-decoration: none; cursor: pointer; }
.ury-ws .links-widget-box .link-item.is-hover { color: var(--ink-gray-9); text-decoration: underline; text-underline-offset: 2px; }
.ury-ws .shortcut-widget-box.is-hover { border-color: var(--invert-neutral); }
.ury-ws .shortcut-widget-box.is-hover .widget-title { color: var(--invert-neutral); }

/* dashboard chart */
.ury-ws .widget.dashboard-widget-box { min-height: 240px; border: 1px solid var(--border-color); }
.ury-ws .dashboard-widget-box .widget-head { padding: 4px 8px; }
.ury-ws .dashboard-widget-box .widget-subtitle { font-size: 12px; color: var(--text-muted); margin-top: var(--margin-xs, 5px); }
.ury-ws .dashboard-widget-box .widget-body { text-align: start; padding: 0 8px 8px; }
.ury-ws svg.frappe-chart { display: block; overflow: visible; }
.ury-ws .frappe-chart .chart-label, .ury-ws .frappe-chart .legend-label { fill: var(--ink-gray-6); font-size: 10px; font-weight: 400; }
.ury-ws .frappe-chart .y-axis-label { text-anchor: end; }
.ury-ws .frappe-chart .x-axis-label { text-anchor: middle; }
.ury-ws .frappe-chart .grid-line { stroke: var(--outline-gray-1); stroke-width: 1; stroke-dasharray: 2 2; }
.ury-ws .frappe-chart .base-line { stroke: var(--outline-gray-2); stroke-width: 1; }
.ury-ws .frappe-chart .dataset-line { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
.ury-ws .frappe-chart .data-point { stroke: var(--card-bg); stroke-width: 1; }
.ury-ws .frappe-chart .donut-path { stroke: var(--card-bg); stroke-width: 1; }
.ury-ws .dashboard-widget-box .widget-footer { height: 0; }
.ury-ws .frappe-chart .ch-1 { --ch: var(--blue-500); } .ury-ws .frappe-chart .ch-2 { --ch: var(--green-500); }
.ury-ws .frappe-chart .ch-3 { --ch: var(--orange-500); } .ury-ws .frappe-chart .ch-4 { --ch: var(--purple-500); }
.ury-ws .frappe-chart .ch-5 { --ch: var(--cyan-500); }
.ury-ws .frappe-chart .dataset-line { stroke: var(--blue-500); }
.ury-ws .frappe-chart .data-point, .ury-ws .frappe-chart .bar, .ury-ws .frappe-chart .donut-path, .ury-ws .frappe-chart .legend-dot { fill: var(--ch, var(--blue-500)); }
.ury-ws .frappe-chart .area-fill { fill: var(--blue-500); opacity: .12; stroke: none; }
.ury-ws .frappe-chart .bar { rx: 2; }
